// Normalise les offres APEC en SIGNAUX de recrutement Salesforce.
// Une entreprise qui recrute un profil Salesforce investit dans Salesforce
// MAINTENANT : c'est public, date et verifiable. Bien mieux qu'une liste
// sectorielle. Aucune donnee personnelle : uniquement des organisations.
const MOTS = ['salesforce', 'sales cloud', 'service cloud', 'crm'];
// Les ESN et cabinets recrutent pour placer : ce sont des PARTENAIRES potentiels,
// pas des clients finaux. On les marque pour que le Commercial adapte son approche.
const ESN = ['capgemini', 'akkodis', 'sopra', 'atos', 'cgi', 'accenture', 'devoteam',
             'mc2i', 'onepoint', 'inetum', 'talan', 'wavestone', 'alten', 'expleo',
             'syd groupe', 'sii ', 'astek', 'ausy', 'modis'];
// Certaines annonces sont diffusees par un SITE D'EMPLOI, pas par l'employeur :
// l'APEC renvoie alors le diffuseur dans nomCommercial. Contacter "Handicap Job"
// en croyant demarcher un prospect serait une perte de temps. On les marque.
const DIFFUSEURS = ['hellowork', 'meteojob', 'direct emploi', 'handicap job',
                    'collective', 'jobology', 'talent.com', 'indeed', 'regionsjob',
                    'cadremploi', 'keljob', 'monster'];
const sortie = [];

for (const item of $input.all()) {
  const res = item.json.resultats || [item.json];
  for (const o of res) {
    const titre = (o.intitule || '').toLowerCase();
    // Le signal doit etre dans l'INTITULE du poste, pas perdu dans le corps
    // de l'annonce : sinon on remonte des commerciaux ascenseurs.
    if (!MOTS.some(m => titre.includes(m))) continue;

    const ent = (o.nomCommercial || '').trim();
    if (!ent) continue;

    const entBas = ent.toLowerCase();
    const estEsn = ESN.some(e => entBas.includes(e));
    const estDiffuseur = DIFFUSEURS.some(x => entBas.includes(x));
    // Salesforce nomme explicitement vaut mieux qu'un CRM generique.
    const precis = titre.includes('salesforce');

    sortie.push({ json: {
      signal_type: estDiffuseur ? 'Recrutement SF (employeur a identifier)'
                 : (estEsn ? 'Recrutement SF (ESN/partenaire)' : 'Recrutement Salesforce'),
      signal_source: 'APEC',
      signal_url: 'https://www.apec.fr/candidat/recherche-emploi.html/emploi/detail-offre/' + (o.numeroOffre || ''),
      signal_date: (o.datePublication || '').slice(0, 10),
      signal_resume: (o.intitule || '') + ' — ' + (o.lieuTexte || ''),
      entreprise: ent,
      echeance: null,
      reference: 'APEC-' + (o.numeroOffre || ''),
      // Un diffuseur masque l'employeur : le signal reste vrai mais demande
      // une recherche supplementaire, donc score minore.
      score_signal: (precis ? 8 : 6) + (estEsn ? 0 : 1) - (estDiffuseur ? 2 : 0)
    }});
  }
}
return sortie;
